mask=(im[:,:,0]>im[:,:,1]*1.35)&(im[:,:,0]>im[:,:,2]*1.25)&(im[:,:,0]>70)
l,n=label(mask)
st=[]
for i in range(1,n+1):
 y,x=np.where(l==i); area=len(x)
 if area>20:st.append((area,x.min(),y.min(),x.max()+1,y.max()+1,x.mean(),y.mean()))
for v in sorted(st,reverse=True)[:20]:print(v)
